import{_ as t,a,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"计算机网络原理","description":"通过可靠传输、路由与拥塞控制理解网络协议的设计取舍。","frontmatter":{"title":"计算机网络原理","description":"通过可靠传输、路由与拥塞控制理解网络协议的设计取舍。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 网络与操作系统","summary":"通过可靠传输、路由与拥塞控制理解网络协议的设计取舍。","status":"active","related":[{"title":"计算机网络基础教程（第3版）","link":"/life/personal/books/computing/network-foundations","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络简介实验手册","link":"/life/personal/books/computing/network-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络互连技术","link":"/life/personal/books/computing/internetworking","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络技术教程","link":"/life/personal/books/computing/network-technology","kind":"书籍导读","scope":"general","audience":"general"},{"title":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Linux命令行与shell脚本编程大全（第4版）","link":"/life/personal/books/computing/linux-shell","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab"},"next":{"text":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab"},"next":{"text":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65"}},"headers":[],"relativePath":"life/personal/books/computing/network-principles.md","filePath":"life/personal/books/computing/network-principles.md"}'),o={name:"life/personal/books/computing/network-principles.md"};function i(l,e,s,d,p,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="计算机网络原理" tabindex="-1">计算机网络原理 <a class="header-anchor" href="#计算机网络原理" aria-label="Permalink to &quot;计算机网络原理&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 网络与操作系统</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书的阅读定位是回答网络技术背后的“为什么”：为什么需要分层，为什么可靠传输需要序号与确认，为什么发送速率必须受限制。适合已能完成基础配置、想进一步解释协议行为的读者。</p><p>它与实验手册可以形成互补：实验提供可观察的现象，原理学习帮助判断现象是正常机制、资源限制，还是配置错误。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>版本待确认。</strong> “计算机网络原理”有多种作者与教材版本，目前不补写未经确认的作者和目录。以下为本站主题导读，不是原书目录。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>《计算机网络原理》作者未确定，不能把它直接认作谢希仁、Tanenbaum 或其他作者的教材。应以完整题名、版权页和 ISBN 找到出版社记录，再核对作者研究或教学背景；当前只按网络协议原理主题提供导读，不宣称本册具有某种认证或课程地位。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合掌握基本联网操作、希望理解可靠传输、路由与拥塞原因的读者。开发者可重点连接缓冲、重传与应用超时；准备课程考试者则应按已确认教材的公式和习题范围学习。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>原理问题</th></tr></thead><tbody><tr><td>分层与端到端设计</td><td>理解分层如何降低复杂度，也思考跨层信息缺失会带来什么限制。</td></tr><tr><td>传输与编码</td><td>区分信道能力、传输速率和误码，理解物理约束如何影响上层设计。</td></tr><tr><td>差错与可靠交付</td><td>用停止等待和滑动窗口分析确认、超时、重传与重复检测。</td></tr><tr><td>介质访问与交换</td><td>理解共享介质冲突和交换网络转发，比较不同访问方式的适用条件。</td></tr><tr><td>路由算法</td><td>从图模型出发理解路径计算，再考虑信息延迟、故障与收敛。</td></tr><tr><td>端到端传输</td><td>比较流量控制与拥塞控制，分别识别接收端能力和网络承载能力。</td></tr><tr><td>应用协议与命名</td><td>理解名称、地址和服务的分工，追踪 DNS 与应用请求之间的依赖。</td></tr><tr><td>网络性能分析</td><td>将排队、丢包和重传联系起来，用测量解释平均时延与尾延迟的差异。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>理解协议，先找出它要应对的失败。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>从“接收端处理变慢”出发，推演接收缓冲、通告窗口、发送等待与应用超时之间的关系，再与链路拥塞引发的丢包作比较。收获是能够区分接收能力限制与网络承载限制，而不把所有延迟都称为带宽问题。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>理论学习若没有可观察现象，容易停留在流程背诵；反过来，单次抓包也不能说明所有实现与路径。原书身份未明，不评价其推导深度；建议用规范理解机制，再用实验验证一组受控条件。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给常遇到网络现象却说不清原因的人：沿失败场景读原理，协议字段会更容易理解。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名来自本次书单；准确目录需按作者与 ISBN 核对。</li><li><a href="https://www.rfc-editor.org/rfc/rfc9293" target="_blank" rel="noopener noreferrer">RFC 9293：TCP 规范</a>：可靠传输机制的补充参考。</li><li><a href="https://www.rfc-editor.org/rfc/rfc5681" target="_blank" rel="noopener noreferrer">RFC 5681：TCP 拥塞控制</a>：拥塞控制原理的补充参考，不是教材章节来源。</li></ul>',26)])])}const k=t(o,[["render",i]]);export{u as __pageData,k as default};
